package vn.eduassistant.backend.service;

import org.springframework.stereotype.Service;
import vn.eduassistant.backend.core.Json;
import java.util.*;

/** Optional provider sanity check; it can make billable calls when AI keys are configured. */
@Service
public class LiveAiEvaluationService {
    private static final String STANDARD="123 Đường Lê Lợi, Phường Bến Nghé, Quận 1, TP. Hồ Chí Minh";
    private final AddressService addresses;private final RuleEngineService rules;
    public LiveAiEvaluationService(AddressService addresses,RuleEngineService rules){this.addresses=addresses;this.rules=rules;}
    public Map<String,Object> run(){String[][] scenarios={{"LIVE-01-STANDARD","Địa chỉ chuẩn",STANDARD},{"LIVE-02-SHORTCUTS","Địa chỉ viết tắt","123 le loi, p ben nghe, q1, tphcm"},{"LIVE-03-MISSING-WARD","Thiếu phường","123 Đường Lê Lợi, Quận 1, TP. Hồ Chí Minh"},{"LIVE-04-CONFLICT","Địa chỉ mâu thuẫn","12 Nguyễn Trãi, Phường Bến Thành, Quận 1, TP. Hồ Chí Minh"},{"LIVE-05-AMBIGUOUS","Đầu vào khó","123/4 Lê Lợi, khu phố gần chợ Bến Thành, TP HCM"}};
        Map<String,Object>student=UserService.map("studentCode","LIVE-TEST-001","fullName","Nguyen Van A","academicStatus","ACTIVE","courseStartDate","2022-09-05","courseEndDate","2027-06-30","currentTermActive",true,"hasCurrentSchedule",true,"registeredPermanentAddress",STANDARD,"sourceType","SYNTHETIC_TEST_SIS","verificationStatus","TEST_VERIFIED");
        List<Map<String,Object>> results=new ArrayList<Map<String,Object>>();for(String[] s:scenarios){Map<String,Object> address=addresses.normalize(s[2],"PERMANENT"),ctx=UserService.map("modeUsed",address.get("modeUsed"),"isLive",address.get("isLive"),"isFallback",address.get("isFallback"),"isSynthetic",address.get("isSynthetic"),"provider",address.get("provider"),"apiCallPerformed",address.get("apiCallPerformed"));Map<String,Object> claim=UserService.map("studentCode",student.get("studentCode"),"fullName",student.get("fullName"),"addressType","PERMANENT","declaredAddress",s[2]);Map<String,Object> data=UserService.map("id",s[0],"studentCode",student.get("studentCode"),"studentName",student.get("fullName"),"description",s[2],"studentClaim",claim,"institutionalFacts",new LinkedHashMap<String,Object>(student),"authoritativeInstitutionalFacts",new LinkedHashMap<String,Object>(student),"addressAnalysis",address,"aiMetadata",ctx);Map<String,Object> evaluation=UserService.map("evaluationMode","DETERMINISTIC_TEST","allowSyntheticVerifiedInstitutionalFacts",true);Map<String,Object> verdict=rules.evaluate(data,null,student,ctx,evaluation);results.add(UserService.map("caseId",s[0],"caseName",s[1],"input",s[2],"provider",address.get("provider"),"model",address.get("model"),"apiCallPerformed",Json.bool(address.get("apiCallPerformed")),"apiAttempts",address.get("apiAttempts"),"latencyMs",address.get("durationMs"),"parsedFields",address.get("parsed"),"confidence",address.get("confidence"),"fallbackStatus",Json.bool(address.get("isFallback"))?"FALLBACK":"NONE","ruleDecision",verdict.get("decision"),"escalationReason",verdict.get("escalationReason")));}
        Set<String>providers=new TreeSet<String>(),models=new TreeSet<String>();int calls=0,fallBacks=0,live=0,attempts=0;for(Map<String,Object>r:results){if(r.get("provider")!=null&&!Json.str(r.get("provider")).isEmpty())providers.add(Json.str(r.get("provider")));if(r.get("model")!=null&&!Json.str(r.get("model")).isEmpty())models.add(Json.str(r.get("model")));if(Json.bool(r.get("apiCallPerformed")))calls++;if("FALLBACK".equals(r.get("fallbackStatus")))fallBacks++;if(!"DETERMINISTIC_PARSER".equals(r.get("provider")))live++;if(r.get("apiAttempts") instanceof Number)attempts+=((Number)r.get("apiAttempts")).intValue();}
        return UserService.map("evaluationType","LIVE_AI_END_TO_END_SANITY_CHECK","aiCallsPerformed",calls>0,"provider",providers.size()==1?providers.iterator().next():providers.isEmpty()?Collections.singletonList("NONE"):providers,"model",models.size()==1?models.iterator().next():models.isEmpty()?Collections.singletonList("NONE"):models,"cases",results.size(),"liveSuccessCount",live,"fallbackCount",fallBacks,"apiAttempts",attempts,"results",results);
    }
}
